INSERT INTO `knowledge_doc` VALUES (1,'规章制度','家庭经济困难学生认定工作坚持实事求是、客观公平的原则。认定等级分为特别困难、比较困难、一般困难三档。申请条件：1. 家庭经济困难，无力支付学习和生活基本费用；2. 遵守学校规章制度，品行良好；3. 学习努力，积极向上。认定程序：个人申请→班级评议→学院审核→学校审定。所需材料：《家庭经济困难学生认定申请表》、家庭经济困难证明、低保证或建档立卡证明等。','2026-09-12 15:19:04.204904','贫困认定,家庭经济困难,助学金,申请条件,认定办法',10,'学校官网',1,'家庭经济困难学生认定办法','2026-09-12 15:19:04.204904',1),(2,'奖助政策','国家奖学金用于奖励特别优秀的全日制本专科学生。奖励标准为每人每年8000元。申请条件：1. 热爱社会主义祖国，拥护中国共产党的领导；2. 遵守宪法和法律，遵守学校规章制度；3. 诚实守信，道德品质优良；4. 在校期间学习成绩优异，社会实践、创新能力、综合素质等方面特别突出。评审程序：个人申请→学院评审→学校审核→报教育部审批。','2026-09-12 15:19:04.212871','国家奖学金,8000元,奖学金,评审,优秀学生',9,'学生工作处',1,'国家奖学金评审办法','2026-09-12 15:19:04.212871',1),(3,'奖助政策','国家励志奖学金用于奖励资助品学兼优的家庭经济困难全日制本专科学生。奖励标准为每人每年5000元。申请条件：1. 热爱社会主义祖国，拥护中国共产党的领导；2. 遵守宪法和法律，遵守学校规章制度；3. 诚实守信，道德品质优良；4. 在校期间学习成绩优秀；5. 家庭经济困难，生活俭朴。同一学年内，获得国家励志奖学金的学生可以同时申请并获得国家助学金，但不能同时获得国家奖学金。','2026-09-12 15:19:04.219825','励志奖学金,5000元,品学兼优,家庭困难,助学金',8,'学生工作处',1,'国家励志奖学金评审办法','2026-09-12 15:19:04.219825',1),(4,'办事流程','学生请假分为病假、事假、公假三种。请假审批权限：1. 请假1天以内，由辅导员审批；2. 请假2-3天，由学院分管学生工作的领导审批；3. 请假4-7天，由学院分管教学工作的领导审批；4. 请假超过7天，由教务处审批。请假流程：填写《学生请假申请表》→附相关证明材料→按审批权限逐级审批→审批通过后交辅导员备案。病假需附校医院或县级以上医院诊断证明。请假期满应及时销假。','2026-09-12 15:19:04.225416','请假,病假,事假,审批,流程,辅导员',10,'教务处',1,'学生请假管理规定','2026-09-12 15:19:04.225416',1),(5,'办事流程','在读证明用于证明学生在校就读身份。办理方式：1. 线上办理：登录教务系统→学生服务→证明开具→选择在读证明→提交申请→审核通过后可下载电子版；2. 线下办理：携带学生证到教务处学籍管理科（第一教学楼2楼）办理。办理时间：工作日9:00-11:30，15:00-17:00。中英文对照证明需额外注明用途。一般1-2个工作日办结。','2026-09-12 15:19:04.230746','在读证明,学籍,证明开具,教务处,办理',9,'教务处',1,'在读证明办理指南','2026-09-12 15:19:04.230746',1),(6,'办事流程','成绩单分为中文成绩单和中英文对照成绩单。办理方式：1. 自助打印：使用校园卡在自助打印机（图书馆一楼、第一教学楼大厅）打印，免费打印5次/学期；2. 线上申请：登录教务系统申请，审核后到教务处领取；3. 线下办理：携带学生证到教务处办理。盖章成绩单用于出国、就业等用途，需到教务处盖章。中英文对照成绩单办理需3个工作日。','2026-09-12 15:19:04.235267','成绩单,打印,盖章,中英文,自助打印',9,'教务处',1,'成绩单办理指南','2026-09-12 15:19:04.235267',1),(7,'办事流程','宿舍设施损坏可通过以下方式报修：1. 线上报修：通过校园服务平台提交报修申请，说明故障类型、位置和描述；2. 电话报修：拨打后勤维修热线0771-3234567；3. 现场报修：到宿舍管理处登记。报修范围：水电故障、门窗损坏、家具维修、空调故障、网络问题等。维修响应时间：一般问题24小时内响应，紧急问题（如水管爆裂、电路故障）2小时内响应。维修完成后请进行满意度评价。','2026-09-12 15:19:04.240610','报修,宿舍,维修,水电,后勤,故障',10,'后勤管理处',1,'宿舍报修服务指南','2026-09-12 15:19:04.240610',1),(8,'办事流程','校园卡是学生在校期间的重要证件，可用于食堂消费、图书馆借阅、宿舍门禁、考试身份验证等。办理：新生入学时统一办理，遗失补办需到校园卡服务中心（第一食堂旁）办理，工本费20元。充值：可通过校园APP线上充值，或在食堂充值点现金充值。挂失：发现校园卡遗失应立即通过校园APP或到服务中心挂失，避免被盗刷。校园卡服务中心工作时间：工作日9:00-17:00。','2026-09-12 15:19:04.245096','校园卡,补办,充值,挂失,消费,门禁',8,'信息网络中心',1,'校园卡办理与使用指南','2026-09-12 15:19:04.245096',1),(9,'规章制度','学生可在第一学年第二学期申请转专业。申请条件：1. 在读一年级全日制本科生；2. 思想品德良好，遵纪守法；3. 第一学期所学课程成绩全部及格；4. 身体条件符合转入专业要求。申请流程：1. 学生向所在学院提出申请，填写《转专业申请表》；2. 所在学院审核同意；3. 转入学院组织考核（笔试+面试）；4. 教务处审批并公示。每个学生只能转专业一次。艺术类、体育类专业不得转入普通类专业。','2026-09-12 15:19:04.249260','转专业,申请,考核,教务处,一年级',7,'教务处',1,'转专业管理办法','2026-09-12 15:19:04.249260',1),(10,'部门联系方式','学生工作处：办公地点-校园服务大厅2楼；电话-0771-3234500；邮箱-xsc@gxu.edu.cn；负责奖助学金、学生管理、心理健康教育等。\n教务处：办公地点-第一教学楼2楼；电话-0771-3234501；邮箱-jwc@gxu.edu.cn；负责学籍管理、课程安排、考试安排、证明开具等。\n后勤管理处：办公地点-后勤楼；电话-0771-3234567；邮箱-hqch@gxu.edu.cn；负责宿舍管理、报修服务、食堂管理等。\n图书馆：电话-0771-3234560；负责图书借阅、电子资源等。\n校医院：电话-0771-3234610（急诊24小时）。','2026-09-12 15:19:04.254830','联系方式,学工处,教务处,后勤,图书馆,校医院,电话',10,'学校官网',1,'学生工作处联系方式','2026-09-12 15:19:04.254830',1);
/*!40000 ALTER TABLE `knowledge_doc` ENABLE KEYS */;
UNLOCK TABLES;

