INSERT INTO `notification` VALUES (1,'教务','各学院、各班级：现将2025-2026学年第二学期期末考试安排通知如下：考试时间为第18-20周，请同学们提前做好复习准备。具体考试安排请登录教务系统查询。','2026-09-12 15:19:04.163271','教务处',_binary '\0',_binary '','2026-09-12 15:19:04.163271',1,1,'期末考试安排通知，请同学们及时查看。','关于2025-2026学年第二学期期末考试安排的通知',285),(2,'学工','各学院：为做好2026年家庭经济困难学生认定工作，现将有关事项通知如下：一、认定对象为全日制在校本科生；二、申请时间为9月15日-9月30日；三、需提交《家庭经济困难学生认定申请表》及相关证明材料。','2026-09-12 15:19:04.172393','学生工作处',_binary '\0',_binary '\0','2026-09-12 15:19:04.172393',1,1,'家庭经济困难学生认定工作开始，请符合条件的同学及时申请。','关于开展2026年家庭经济困难学生认定工作的通知',155),(3,'后勤','因水管维修，学生宿舍1-3栋将于9月15日8:00-18:00停水，请同学们提前做好储水准备。给您带来不便，敬请谅解。','2026-09-12 15:19:04.177841','后勤管理处',_binary '',_binary '\0','2026-09-12 15:19:04.177841',1,1,'紧急通知：宿舍区9月15日停水，请提前储水。','关于宿舍区停水通知',193),(4,'学工','根据国务院办公厅通知，结合学校实际，2026年国庆节放假安排如下：10月1日至7日放假调休，共7天。10月10日（星期六）上班上课。请各单位做好值班和安全工作。','2026-09-12 15:19:04.182330','学校办公室',_binary '\0',_binary '','2026-09-12 15:19:04.182330',1,1,'国庆节放假7天，请合理安排假期。','关于2026年国庆节放假安排的通知',459),(5,'教务','为帮助同学们更好地利用图书馆电子资源，图书馆将举办电子资源使用培训。时间：每周三下午15:00；地点：图书馆三楼电子阅览室；内容：数据库检索、文献管理软件使用等。欢迎同学们参加。','2026-09-12 15:19:04.188591','图书馆',_binary '\0',_binary '\0','2026-09-12 15:19:04.188591',1,1,'图书馆电子资源培训，欢迎参加。','关于图书馆电子资源使用培训的通知',299),(6,'后勤','校园卡充值系统将于9月20日进行升级维护，届时线上充值功能暂停服务，预计维护时间4小时。升级完成后将支持更多支付方式。','2026-09-12 15:19:04.193543','信息网络中心',_binary '\0',_binary '\0','2026-09-12 15:19:04.193543',1,1,'校园卡系统9月20日升级，线上充值暂停。','关于校园卡充值系统升级的通知',36),(7,'学工','学校将于10月15日在体育馆举办2027届毕业生校园招聘会，届时将有100余家企业参会，提供岗位2000余个。请同学们提前准备简历，积极参与。','2026-09-12 15:19:04.200095','招生就业处',_binary '\0',_binary '\0','2026-09-12 15:19:04.200095',1,1,'10月15日校园招聘会，100+企业参会。','关于举办校园招聘会的通知',238);
/*!40000 ALTER TABLE `notification` ENABLE KEYS */;
UNLOCK TABLES;

